CREATE OR REPLACE FUNCTION "public"."apply_territory_points"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$BEGIN
  WITH t AS (
    SELECT
      user_id,
      base_point,
      get_territory_weight(updated_at) AS weight,
      (base_point * get_territory_weight(updated_at)) AS points_delta,
      (updated_at + interval '30 minutes') AS next_process_at
    FROM public.territories
  ),
  -- Update profiles and capture affected rows for history insertion
  updated AS (
    UPDATE public.profiles p
    SET
      total_points = p.total_points + t.points_delta,
      updated_at = now(),
      next_process_at = t.next_process_at
    FROM t
    WHERE p.user_id = t.user_id
    RETURNING p.user_id, t.points_delta
  )
  -- Insert history for each updated row
  INSERT INTO public.point_history (event_type, points_delta, user_id, created_at)
  SELECT 'territory_maintenance', u.points_delta, u.user_id, now()
  FROM updated u;
END;$$;


ALTER FUNCTION "public"."apply_territory_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_territory_points"("p_user_ids" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$BEGIN
  WITH t AS (
    SELECT
      tr.user_id,
      ROUND((tr.base_point * get_territory_weight(tr.updated_at))::numeric, 2) AS points_delta,
      GREATEST(tr.next_process_at, now()) + interval '30 minutes' AS next_process_at
    FROM public.territories tr
    WHERE tr.user_id = ANY (p_user_ids)
  ),
  -- user별 합산 (안전)
  t_sum AS (
    SELECT
      user_id,
      SUM(points_delta) AS points_delta,
      MAX(next_process_at) AS next_process_at
    FROM t
    GROUP BY user_id
  ),
  updated AS (
    UPDATE public.profiles p
    SET total_points = COALESCE(p.total_points, 0) + s.points_delta
    FROM t_sum s
    WHERE p.user_id = s.user_id
    RETURNING p.user_id, s.points_delta, s.next_process_at
  ),
  history_update AS (
    UPDATE public.point_history ph
    SET points_delta = COALESCE(ph.points_delta, 0) + u.points_delta
    FROM updated u
    WHERE ph.user_id = u.user_id
      AND ph.event_type = 'territory_points'
      AND ph.created_at >= date_trunc('day', now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul'
      AND ph.created_at <  (date_trunc('day', now() AT TIME ZONE 'Asia/Seoul') + interval '1 day') AT TIME ZONE 'Asia/Seoul'
    RETURNING ph.user_id
  ),
  history_insert AS (
    INSERT INTO public.point_history (user_id, event_type, points_delta, created_at)
    SELECT u.user_id, 'territory_points', u.points_delta, now()
    FROM updated u
    WHERE NOT EXISTS (
      SELECT 1
      FROM public.point_history ph
      WHERE ph.user_id = u.user_id
        AND ph.event_type = 'territory_points'
        AND ph.created_at >= date_trunc('day', now() AT TIME ZONE 'Asia/Seoul') AT TIME ZONE 'Asia/Seoul'
        AND ph.created_at <  (date_trunc('day', now() AT TIME ZONE 'Asia/Seoul') + interval '1 day') AT TIME ZONE 'Asia/Seoul'
    )
    RETURNING user_id
  )
  UPDATE public.territories tr
  SET next_process_at = u.next_process_at
  FROM updated u
  WHERE tr.user_id = u.user_id;
END;$$;


ALTER FUNCTION "public"."apply_territory_points"("p_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_territory_worker"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_ids uuid[];
  v_limit integer := 100;
BEGIN
  -- 1) 만료된 row들을 user_id별로 그룹화하여 수집 (GROUP BY 적용)
  WITH expired AS (
    SELECT user_id
    FROM public.territories
    WHERE next_process_at <= now()
    GROUP BY user_id
    LIMIT v_limit
  )
  SELECT array_agg(user_id) INTO v_user_ids FROM expired;

  IF v_user_ids IS NULL OR array_length(v_user_ids,1) = 0 THEN
    RETURN;
  END IF;

  -- 2) 선택된 user_id들에 대해 실제 포인트 적용 호출
  PERFORM public.apply_territory_points(v_user_ids);

  -- 끝
END;
$$;


ALTER FUNCTION "public"."apply_territory_worker"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."clean_geom"("in_geom" "public"."geometry") RETURNS "public"."geometry"
    LANGUAGE "plpgsql"
    AS $$DECLARE
  simplified_geom geometry;
  ln geometry;
  _work_srid integer;
  _geom_srid integer := 4326;
  _tol_meters double precision := 3.0;
BEGIN
  IF in_geom IS NULL THEN
    RETURN NULL;
  END IF;

  -- 입력 SRID가 없으면 4326 가정
  IF ST_SRID(in_geom) IS NULL OR ST_SRID(in_geom) = 0 THEN
    in_geom := ST_SetSRID(in_geom, 4326);
  END IF;

  -- 1) geometry 위치에 맞는 작업용 UTM SRID 자동 선택
  _work_srid := public.get_best_utm_srid(in_geom);

  -- 2) 입력 geometry를 작업 좌표계(미터 단위)로 변환
  simplified_geom := ST_Transform(in_geom, _work_srid);

  -- 3) 단순화 시도 (5m 기준)
  BEGIN
    simplified_geom := ST_SimplifyPreserveTopology(simplified_geom, _tol_meters);
  EXCEPTION WHEN OTHERS THEN
    simplified_geom := ST_Transform(in_geom, _work_srid);
  END;

  -- 4) 다시 4326으로 변환
  simplified_geom := ST_Transform(simplified_geom, _geom_srid);

  -- 5) 라인 병합 및 MULTILINESTRING 처리
  ln := ST_LineMerge(simplified_geom);

  IF GeometryType(ln) = 'MULTILINESTRING' THEN
    ln := (
      SELECT (st).geom
      FROM (SELECT ST_Dump(ln) AS st) AS foo
      ORDER BY ST_Length(ST_Transform((st).geom, public.get_best_utm_srid((st).geom))) DESC
      LIMIT 1
    );
  END IF;

  RETURN ln;

EXCEPTION WHEN OTHERS THEN
  -- 예외 발생 시 원본 지오메트리를 안전하게 반환
  RETURN in_geom;
END;$$;


ALTER FUNCTION "public"."clean_geom"("in_geom" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_area_and_base"("geom" "public"."geometry") RETURNS TABLE("area_m2" double precision, "base_point" double precision)
    LANGUAGE "plpgsql"
    AS $$DECLARE
  area_srid integer;
  computed_area double precision;
BEGIN
  -- 기본값
  area_m2 := 0;
  base_point := 0;

  IF geom IS NULL THEN
    -- geom이 NULL이면 0값을 반환하고 종료
    RETURN NEXT;
    RETURN;
  END IF;

  BEGIN
    -- 위치 기반 UTM SRID 자동 선택
    area_srid := public.get_best_utm_srid(geom);

    -- 선택된 UTM 좌표계에서 면적 계산
    computed_area := ST_Area(ST_Transform(geom, area_srid));
  EXCEPTION WHEN OTHERS THEN
    computed_area := 0;
  END;

  IF computed_area IS NULL OR computed_area <= 0 THEN
    area_m2 := 0;
    base_point := 0;
  ELSE
    area_m2 := computed_area;

    -- base_point 계산: log10(area_m2)
    BEGIN
      base_point := (LN(area_m2) / LN(10));
    EXCEPTION WHEN OTHERS THEN
      base_point := 0;
    END;
  END IF;

  -- OUT 변수 값을 한 행으로 반환
  RETURN NEXT;
  RETURN;
END;$$;


ALTER FUNCTION "public"."compute_area_and_base"("geom" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_profile_after_auth_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$DECLARE
  _nick text;
BEGIN
  IF EXISTS (SELECT 1 FROM public.profiles WHERE user_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  IF NEW.email IS NOT NULL AND NEW.email <> '' THEN
    _nick := split_part(NEW.email, '@', 1);
  ELSE
    _nick := NULL;
  END IF;

  INSERT INTO public.profiles (user_id, nick_name)
  VALUES (NEW.id, _nick)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN NEW;
END;$$;


ALTER FUNCTION "public"."create_profile_after_auth_insert"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_profile_after_signup"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.profile WHERE user_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.profile (user_name, nick_name, color_hex, user_id, created_at)
  VALUES (
    COALESCE(NEW.email, ''),
    split_part(COALESCE(NEW.email, ''), '@', 1),
    ("#" || substring(md5(NEW.id::text) for 6)),
    NEW.id,
    now()
  );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."create_profile_after_signup"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."geom_to_polygon"("in_geom" "public"."geometry") RETURNS "public"."geometry"
    LANGUAGE "plpgsql"
    AS $$DECLARE
  ln geometry := in_geom;
  ln_closed geometry;
  ln_noded geometry;
  poly geometry;
  srid integer;
  work_srid integer;
  dist_m double precision;
BEGIN
  IF ln IS NULL OR ST_IsEmpty(ln) THEN
    RETURN NULL;
  END IF;

  srid := ST_SRID(ln);
  IF srid IS NULL OR srid = 0 THEN
    srid := 4326;
    ln := ST_SetSRID(ln, srid);
  END IF;

  -- 중복점 제거
  ln := ST_RemoveRepeatedPoints(ln);

  IF ST_NPoints(ln) < 3 THEN
    RETURN NULL;
  END IF;

  -- 시작점-끝점 거리 계산
  work_srid := public.get_best_utm_srid(ln);
  dist_m := ST_Distance(
    ST_Transform(ST_StartPoint(ln), work_srid),
    ST_Transform(ST_EndPoint(ln), work_srid)
  );

  ------------------------------------------------------------------
  -- 1) 시작점-끝점이 40m 이내면: 기존 방식 우선
  ------------------------------------------------------------------
  IF dist_m <= 40 THEN
    IF NOT ST_IsClosed(ln) THEN
      ln_closed := ST_AddPoint(ln, ST_StartPoint(ln));
    ELSE
      ln_closed := ln;
    END IF;

    BEGIN
      poly := ST_BuildArea(ST_UnaryUnion(ln_closed));
    EXCEPTION WHEN OTHERS THEN
      poly := NULL;
    END;

    IF poly IS NULL OR ST_IsEmpty(poly) THEN
      BEGIN
        poly := ST_MakePolygon(ln_closed);
      EXCEPTION WHEN OTHERS THEN
        poly := NULL;
      END;
    END IF;
  END IF;

  ------------------------------------------------------------------
  -- 2) 위 방식 실패했거나, 시작점-끝점이 40m 초과면:
  --    내부 폐곡선 추출 방식
  ------------------------------------------------------------------
  IF poly IS NULL OR ST_IsEmpty(poly) THEN
    BEGIN
      ln_noded := ST_Node(ln);
    EXCEPTION WHEN OTHERS THEN
      ln_noded := ln;
    END;

    BEGIN
      poly := ST_BuildArea(ln_noded);
    EXCEPTION WHEN OTHERS THEN
      poly := NULL;
    END;
  END IF;

  ------------------------------------------------------------------
  -- 3) Polygon / MultiPolygon만 추출
  ------------------------------------------------------------------
  IF poly IS NOT NULL AND NOT ST_IsEmpty(poly) THEN
    poly := ST_CollectionExtract(poly, 3);
  END IF;

  IF poly IS NULL OR ST_IsEmpty(poly) THEN
    RETURN NULL;
  END IF;

  ------------------------------------------------------------------
  -- 4) 유효성 보정
  ------------------------------------------------------------------
  IF NOT ST_IsValid(poly) THEN
    poly := ST_MakeValid(poly);
    poly := ST_CollectionExtract(poly, 3);
  END IF;

  IF poly IS NULL OR ST_IsEmpty(poly) THEN
    RETURN NULL;
  END IF;

  RETURN ST_SetSRID(poly, srid);
END;$$;


ALTER FUNCTION "public"."geom_to_polygon"("in_geom" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_best_utm_srid"("in_geom" "public"."geometry") RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    g4326 geometry;
    c geometry;
    lon double precision;
    lat double precision;
    zone_num integer;
    srid_out integer;
BEGIN
    IF in_geom IS NULL THEN
        RETURN 4326;
    END IF;

    -- 입력 SRID가 없으면 4326 가정
    IF ST_SRID(in_geom) IS NULL OR ST_SRID(in_geom) = 0 THEN
        g4326 := ST_SetSRID(in_geom, 4326);
    ELSIF ST_SRID(in_geom) <> 4326 THEN
        g4326 := ST_Transform(in_geom, 4326);
    ELSE
        g4326 := in_geom;
    END IF;

    -- 중심점 추출
    c := ST_Centroid(g4326);
    lon := ST_X(c);
    lat := ST_Y(c);

    -- 경도 범위 보정
    IF lon < -180 THEN lon := -180; END IF;
    IF lon > 180 THEN lon := 180; END IF;

    zone_num := floor((lon + 180) / 6)::integer + 1;

    -- 안전 보정
    IF zone_num < 1 THEN zone_num := 1; END IF;
    IF zone_num > 60 THEN zone_num := 60; END IF;

    -- 북반구 / 남반구 구분
    IF lat >= 0 THEN
        srid_out := 32600 + zone_num;  -- WGS 84 / UTM zone N
    ELSE
        srid_out := 32700 + zone_num;  -- WGS 84 / UTM zone S
    END IF;

    RETURN srid_out;
END;
$$;


ALTER FUNCTION "public"."get_best_utm_srid"("in_geom" "public"."geometry") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_profile_rank_count"("p_user_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE
    AS $$
  select count(*)
  from public.profiles
  where total_points > (
    select total_points
    from public.profiles
    where user_id = p_user_id
  );
$$;


ALTER FUNCTION "public"."get_profile_rank_count"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_territories_geojson"("in_srid" integer DEFAULT 4326, "in_minx" double precision DEFAULT NULL::double precision, "in_miny" double precision DEFAULT NULL::double precision, "in_maxx" double precision DEFAULT NULL::double precision, "in_maxy" double precision DEFAULT NULL::double precision, "in_limit" integer DEFAULT 1000) RETURNS TABLE("user_id" "uuid", "nick_name" "text", "color_hex" "text", "area" double precision, "geom_json" "text")
    LANGUAGE "sql" STABLE
    AS $$
  select
    t.user_id,
    p.nick_name,
    p.color_hex,
    t.area,
    ST_AsGeoJSON(ST_Transform(t.geom, in_srid)) as geom_json
  from public.territories t
  join public.profiles p on p.user_id = t.user_id
  where
    (
      in_minx is null or in_miny is null or in_maxx is null or in_maxy is null
      or ST_Intersects(
        t.geom,
        ST_Transform(
          ST_MakeEnvelope(in_minx, in_miny, in_maxx, in_maxy, in_srid),
          ST_SRID(t.geom)
        )
      )
    )
  limit LEAST(GREATEST(in_limit, 1), 5000);
$$;


ALTER FUNCTION "public"."get_territories_geojson"("in_srid" integer, "in_minx" double precision, "in_miny" double precision, "in_maxx" double precision, "in_maxy" double precision, "in_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_territory_weight"("updated_at" timestamp with time zone) RETURNS double precision
    LANGUAGE "sql" STABLE
    AS $$
  select case
    when now() - updated_at < interval '4 hours' then 1.0
    when now() - updated_at < interval '8 hours' then 0.7
    when now() - updated_at < interval '12 hours' then 0.3
    else 0.1
  end;
$$;


ALTER FUNCTION "public"."get_territory_weight"("updated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_info"("p_user_id" "uuid") RETURNS TABLE("id" bigint, "nick_name" character varying, "total_points" double precision, "color_hex" character varying, "created_at" timestamp with time zone, "user_id" "uuid", "area" double precision, "rank" bigint)
    LANGUAGE "sql" STABLE
    AS $$
  SELECT
    p.id,
    p.nick_name,
    p.total_points,
    p.color_hex,
    p.created_at,
    p.user_id,
    COALESCE(SUM(t.area), 0)::double precision AS area,
    RANK() OVER (ORDER BY p.total_points DESC) AS rank
  FROM profiles p
  LEFT JOIN territories t
    ON p.user_id = t.user_id
  GROUP BY
    p.id,
    p.nick_name,
    p.total_points,
    p.color_hex,
    p.created_at,
    p.user_id
  HAVING p.user_id = p_user_id;
$$;


ALTER FUNCTION "public"."get_user_info"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_run_points"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  -- 1) point_history 기록
  INSERT INTO public.point_history (event_type, points_delta, created_at, user_id)
  VALUES ('run_created', COALESCE(NEW.point, 0), now(), NEW.user_id);

  -- 2) profiles.total_points 누적
  UPDATE public.profiles
  SET total_points = COALESCE(total_points, 0) + COALESCE(NEW.point, 0)
  WHERE user_id = NEW.user_id;

  -- 3) user_point_daily (KST 기준 일자) 누적 upsert
  INSERT INTO public.user_point_daily (user_id, day_kst, total_points)
  VALUES (
    NEW.user_id,
    (now() AT TIME ZONE 'Asia/Seoul')::date,
    COALESCE(NEW.point, 0)
  )
  ON CONFLICT (user_id, day_kst)
  DO UPDATE
  SET total_points = COALESCE(user_point_daily.total_points, 0) + EXCLUDED.total_points;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_run_points"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."handle_territory_schedule"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$BEGIN
  -- updated_at이 변경되었을 때만 next_process_at 갱신
  IF NEW.updated_at IS DISTINCT FROM OLD.updated_at THEN
    NEW.next_process_at := NEW.updated_at + interval '30 minutes';
  END IF;

  RETURN NEW;
END;$$;


ALTER FUNCTION "public"."handle_territory_schedule"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_run_geometry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    geom_srid integer;
    path_geom_2d geometry;
    ln geometry;
    poly geometry;
    out_geom geometry;
    out_geom_2d geometry;
BEGIN
    IF NEW.path_geom IS NULL THEN
        RETURN NEW;
    END IF;

    -- NEW.path_geom은 Z 보존 (SRID만 보정)
    geom_srid := ST_SRID(NEW.path_geom);
    IF geom_srid IS NULL OR geom_srid = 0 THEN
        geom_srid := 4326;
        NEW.path_geom := ST_SetSRID(NEW.path_geom, geom_srid);
    END IF;

    -- 영토 계산용 2D geometry 별도 생성
    path_geom_2d := ST_SetSRID(ST_Force2D(NEW.path_geom), geom_srid);

    ln := public.clean_geom(path_geom_2d);

    IF ln IS NULL OR ST_IsEmpty(ln) THEN
        RETURN NEW;
    END IF;

    ln := ST_SetSRID(ST_Force2D(ln), geom_srid);

    IF ST_NPoints(ln) < 2 THEN
        RETURN NEW;
    END IF;

    poly := public.geom_to_polygon(ln);

    IF poly IS NULL OR ST_IsEmpty(poly) THEN
        NEW.loop_geom := NULL;
        NEW.area := NULL;
        RETURN NEW;
    END IF;

    -- loop_geom은 기존 정책대로 2D 저장
    out_geom := ST_SetSRID(poly, geom_srid);
    out_geom_2d := ST_SetSRID(ST_Force2D(out_geom), geom_srid);

    NEW.loop_geom := out_geom_2d;
    NEW.area := ST_Area(out_geom_2d::geography);

    PERFORM public.subtract_territory_and_update(out_geom_2d, NEW.user_id);
    PERFORM public.upsert_or_merge_territory(out_geom_2d, NEW.user_id);

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."process_run_geometry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_apply_territory_points_with_lock"("lock_key" bigint DEFAULT '4242424242'::bigint) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- Try to obtain an advisory lock. If not obtained, return false immediately.
  IF NOT pg_try_advisory_lock(lock_key) THEN
    RETURN false;
  END IF;

  BEGIN
    -- Call the existing processing function
    PERFORM public.apply_territory_points();
  EXCEPTION WHEN others THEN
    -- Ensure we release the lock on error, then re-raise
    PERFORM pg_advisory_unlock(lock_key);
    RAISE;
  END;

  -- Release the lock and return true
  PERFORM pg_advisory_unlock(lock_key);
  RETURN true;
END;
$$;


ALTER FUNCTION "public"."run_apply_territory_points_with_lock"("lock_key" bigint) OWNER TO "postgres";


