CREATE OR REPLACE FUNCTION "public"."subtract_territory_and_update"("target_geom" "public"."geometry", "exclude_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$DECLARE
  other_rec RECORD;
  other_geom geometry;
  updated_geom geometry;
  area_m2_var double precision;
  base_point_var double precision;
  geom_srid integer := 4326;         -- 고정 SRID
  min_area_m2 double precision := 100; -- 이 값 미만 자투리 폴리곤 제거
BEGIN
  IF target_geom IS NULL THEN
    RETURN;
  END IF;

  -- target_geom도 SRID 맞춤
  IF ST_SRID(target_geom) <> geom_srid THEN
    BEGIN
      target_geom := ST_Transform(target_geom, geom_srid);
    EXCEPTION WHEN OTHERS THEN
      target_geom := ST_SetSRID(target_geom, geom_srid);
    END;
  END IF;

  FOR other_rec IN
    SELECT user_id, geom
    FROM public.territories
    WHERE user_id IS DISTINCT FROM exclude_user_id
  LOOP
    other_geom := other_rec.geom;

    IF other_geom IS NULL THEN
      CONTINUE;
    END IF;

    -- other_geom SRID 맞추기
    IF ST_SRID(other_geom) <> geom_srid THEN
      BEGIN
        other_geom := ST_Transform(other_geom, geom_srid);
      EXCEPTION WHEN OTHERS THEN
        other_geom := ST_SetSRID(other_geom, geom_srid);
      END;
    END IF;

    -- 겹치지 않으면 스킵
    IF NOT ST_Intersects(other_geom, target_geom) THEN
      CONTINUE;
    END IF;

    BEGIN
      -- 1. 차집합
      updated_geom := ST_Difference(other_geom, target_geom);

      -- 2. 비었으면 NULL
      IF updated_geom IS NULL OR ST_IsEmpty(updated_geom) THEN
        updated_geom := NULL;
      ELSE
        -- 3. 유효화 + SRID 보정
        updated_geom := ST_MakeValid(updated_geom);
        updated_geom := ST_SetSRID(updated_geom, geom_srid);

        -- 4. polygon 계열만 추출 후 자투리 제거
        SELECT
          CASE
            WHEN COUNT(*) = 0 THEN NULL
            ELSE ST_Multi(ST_Union(part_geom))
          END
        INTO updated_geom
        FROM (
          SELECT (ST_Dump(ST_CollectionExtract(updated_geom, 3))).geom AS part_geom
        ) d
        WHERE ST_Area(part_geom::geography) >= min_area_m2;

        -- 5. 다시 후처리
        IF updated_geom IS NULL OR ST_IsEmpty(updated_geom) THEN
          updated_geom := NULL;
        ELSE
          updated_geom := ST_MakeValid(updated_geom);
          updated_geom := ST_SetSRID(updated_geom, geom_srid);
        END IF;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      -- 차집합/가공 중 에러 나면 원본 유지
      updated_geom := other_geom;
    END;

    -- 6. 수정된 geom 기준으로 면적/base_point 재계산
    SELECT area_m2, base_point
    INTO area_m2_var, base_point_var
    FROM public.compute_area_and_base(updated_geom);

    -- 7. 반영
    UPDATE public.territories
    SET geom = updated_geom,
        area = area_m2_var,
        base_point = base_point_var
    WHERE user_id = other_rec.user_id;
  END LOOP;
END;$$;


ALTER FUNCTION "public"."subtract_territory_and_update"("target_geom" "public"."geometry", "exclude_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."upsert_or_merge_territory"("p_out_geom" "public"."geometry", "p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  p_geom_srid integer := 4326;

  user_exist boolean;
  existing_geom geometry;
  normalized_out_geom geometry;
  merged_geom geometry;
  area_m2_var double precision;
  base_point_var double precision;
BEGIN
  IF p_out_geom IS NULL OR p_user_id IS NULL THEN
    RETURN;
  END IF;

  -- 입력 geometry 정규화: SRID 보정 + 2D 강제
  normalized_out_geom := p_out_geom;

  IF ST_SRID(normalized_out_geom) IS NULL OR ST_SRID(normalized_out_geom) = 0 THEN
    normalized_out_geom := ST_SetSRID(normalized_out_geom, p_geom_srid);
  ELSIF ST_SRID(normalized_out_geom) <> p_geom_srid THEN
    BEGIN
      normalized_out_geom := ST_Transform(normalized_out_geom, p_geom_srid);
    EXCEPTION WHEN OTHERS THEN
      normalized_out_geom := ST_SetSRID(normalized_out_geom, p_geom_srid);
    END;
  END IF;

  normalized_out_geom := ST_SetSRID(ST_Force2D(normalized_out_geom), p_geom_srid);

  -- 존재 여부 확인
  SELECT EXISTS(
    SELECT 1
    FROM public.territories
    WHERE user_id = p_user_id
  )
  INTO user_exist;

  IF user_exist THEN
    SELECT geom
    INTO existing_geom
    FROM public.territories
    WHERE user_id = p_user_id
    FOR UPDATE;

    IF existing_geom IS NULL THEN
      merged_geom := normalized_out_geom;
    ELSE
      -- 기존 geometry 정규화: SRID 보정 + 2D 강제
      IF ST_SRID(existing_geom) IS NULL OR ST_SRID(existing_geom) = 0 THEN
        existing_geom := ST_SetSRID(existing_geom, p_geom_srid);
      ELSIF ST_SRID(existing_geom) <> p_geom_srid THEN
        BEGIN
          existing_geom := ST_Transform(existing_geom, p_geom_srid);
        EXCEPTION WHEN OTHERS THEN
          existing_geom := ST_SetSRID(existing_geom, p_geom_srid);
        END;
      END IF;

      existing_geom := ST_SetSRID(ST_Force2D(existing_geom), p_geom_srid);

      BEGIN
        merged_geom := ST_Union(existing_geom, normalized_out_geom);
        merged_geom := ST_MakeValid(merged_geom);
      EXCEPTION WHEN OTHERS THEN
        merged_geom := ST_ConvexHull(ST_Collect(existing_geom, normalized_out_geom));
      END;
    END IF;

    SELECT area_m2, base_point
    INTO area_m2_var, base_point_var
    FROM public.compute_area_and_base(merged_geom);

    UPDATE public.territories
    SET geom = ST_SetSRID(ST_Force2D(merged_geom), p_geom_srid),
        area = area_m2_var,
        base_point = base_point_var,
        updated_at = now()
    WHERE user_id = p_user_id;

  ELSE
    SELECT area_m2, base_point
    INTO area_m2_var, base_point_var
    FROM public.compute_area_and_base(normalized_out_geom);

    INSERT INTO public.territories(user_id, geom, area, base_point, created_at, updated_at)
    VALUES (p_user_id, normalized_out_geom, area_m2_var, base_point_var, now(), now());
  END IF;
END;
$$;


ALTER FUNCTION "public"."upsert_or_merge_territory"("p_out_geom" "public"."geometry", "p_user_id" "uuid") OWNER TO "postgres";

