CREATE TABLE IF NOT EXISTS "public"."point_history" (
    "id" bigint NOT NULL,
    "event_type" character varying NOT NULL,
    "points_delta" double precision NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid"
);


ALTER TABLE "public"."point_history" OWNER TO "postgres";


ALTER TABLE "public"."point_history" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME "public"."point_history_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" bigint NOT NULL,
    "nick_name" character varying NOT NULL,
    "total_points" double precision DEFAULT '0'::double precision NOT NULL,
    "color_hex" character varying DEFAULT '#ff0000'::character varying NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "user_id" "uuid" NOT NULL,
    "height_cm" double precision,
    "weight_kg" double precision,
    CONSTRAINT "profiles_height_cm_check" CHECK ((("height_cm" > (0)::double precision) AND ("height_cm" < (300)::double precision))),
    CONSTRAINT "profiles_weight_kg_check" CHECK ((("weight_kg" > (0)::double precision) AND ("weight_kg" < (500)::double precision)))
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


ALTER TABLE "public"."profiles" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME "public"."profile_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."run_splits" (
    "id" bigint NOT NULL,
    "run_id" bigint NOT NULL,
    "split_index" integer NOT NULL,
    "distance_m" double precision NOT NULL,
    "duration_s" double precision NOT NULL,
    "avg_pace_s_per_km" double precision,
    "avg_speed_mps" double precision,
    "ascent_m" double precision DEFAULT 0,
    "calories" double precision,
    "path_geom" "public"."geometry",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "run_splits_distance_chk" CHECK (("distance_m" > (0)::double precision)),
    CONSTRAINT "run_splits_duration_chk" CHECK (("duration_s" > (0)::double precision)),
    CONSTRAINT "run_splits_split_index_chk" CHECK (("split_index" > 0))
);


ALTER TABLE "public"."run_splits" OWNER TO "postgres";


ALTER TABLE "public"."run_splits" ALTER COLUMN "id" ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME "public"."run_splits_id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



CREATE TABLE IF NOT EXISTS "public"."runs" (
    "id" bigint NOT NULL,
    "started_at" timestamp without time zone NOT NULL,
    "ended_at" timestamp without time zone NOT NULL,
    "duration" double precision NOT NULL,
    "distance" double precision NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "path_geom" "public"."geometry" NOT NULL,
    "loop_geom" "public"."geometry",
    "user_id" "uuid",
    "point" double precision NOT NULL,
    "avg_pace" double precision,
    "calories" double precision,
    "area" double precision DEFAULT 0
);


ALTER TABLE "public"."runs" OWNER TO "postgres";


ALTER TABLE "public"."runs" ALTER COLUMN "id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME "public"."runs_id_seq"
