CREATE TRIGGER create_profile_after_auth_insert AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile_after_auth_insert();

CREATE TRIGGER create_profile_after_auth_insert_trigger AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile_after_auth_insert();


  create policy "Give anon users access to JPG images in folder 1oj01fe_0"
  on "storage"."objects"
  as permissive
  for select
  to public
using (((bucket_id = 'avatars'::text) AND ((storage.extension(name) = 'jpg'::text) OR (storage.extension(name) = 'png'::text))));



  create policy "Give users authenticated access to folder 1oj01fe_0"
  on "storage"."objects"
  as permissive
  for insert
  to public
with check (((bucket_id = 'avatars'::text) AND (auth.role() = 'authenticated'::text)));



